class Solution:
    def earliestAcq(self, logs: list[list[int]], n: int) -> int:
        # Write your solution here
        count = 1
        logs.sort(key=lambda l: l[0])
        conn = list(range(n))
        def find(x):
            while conn[x] != x:
                x = find(conn[x])
            return x

        def union(x, y):
            nonlocal count
            rootx = find(x)
            rooty = find(y)
            if rootx != rooty:
                conn[rooty] = rootx
                count += 1

        for t, x, y in logs:
            union(x, y)
            if count == n:
                return t
        return -1

