class UnionFind:
    def __init__(self, nums: int):
        self.root = [i for i in range(nums)]

    def find(self, i: int):
        while i != self.root[i]:
            i = self.find(self.root[i])
        return i

    def union(self, i: int, j: int):
        rooti = self.find(i)
        rootj = self.find(j)
        if rooti != rootj:
            self.root[rootj] = rooti
        return

