import heapq
class Solution:
    def networkDelayTime(self, times: list[list[int]], n: int, k: int) -> int:
        # Write your solution here

        # build the graph so we know the neighbors
        graph = defaultdict(list)
        for u, v, w in times:
            graph[u].append((v, w))

        # go over the graph using the heap, so to make sure to put the high weight to the bottom of the heap, 
        #so the first seen (w, v) is the minimum distance to v.
        heap = [[0, k]]
        min_dis = {}
        while heap:
            dis, node = heapq.heappop(heap)
            if node in min_dis:
                continue
            min_dis[node] = dis

            # go over the neighbors
            for nei, w in graph[node]:
                if nei not in min_dis:
                    heapq.heappush(heap, [dis + w, nei])

        if len(min_dis) == n:
            return max(min_dis.values())
        else:
            return -1

