    def findMaxAverage(self, nums: list[int], k: int) -> float:

        # initial sum
        cur_sum = sum(nums[:k])
        res = cur_sum / k

        for i in range(k, len(nums)):
            cur_sum += nums[i]
            cur_sum -= nums[i - k]
            res = max(res, cur_sum / k)

