        # [1, 2, 1, 1, 2, 1]
        stack = []
        res = [-1] * len(nums)
        for i in range(len(newn) - 1, -1, -1):
            cur = newn[i]
            while stack and cur >= stack[-1]:
                stack.pop()
            if i < len(nums):
